script:
setTimeout(function() {
    let chart_div = root_element.querySelector('#type-chart');
    let legend_div = root_element.querySelector('#type-legend');

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Sabre Sales Opportunity',
            fields: ['opportunity_type'],
            limit_page_length: 500
        },
        callback: function(r) {
            if (r.message) {
                let types = {};
                r.message.forEach(function(d) {
                    let type = d.opportunity_type || 'No Type';
                    types[type] = (types[type] || 0) + 1;
                });

                let entries = Object.entries(types).sort(function(a, b) {
                    return b[1] - a[1];
                });
                let labels = entries.map(function(e) { return e[0]; });
                let values = entries.map(function(e) { return e[1]; });
                let total = values.reduce(function(a, b) { return a + b; }, 0);

                let colors = ['#BFDDF7', '#64B5F6', '#F48FB1'];

                new frappe.Chart(chart_div, {
                    type: 'pie',
                    data: {
                        labels: labels,
                        datasets: [{ values: values }]
                    },
                    height: 280,
                    colors: colors,
                    isNavigable: true,
                    showLegend: false
                });

                setTimeout(function() {
                    chart_div.querySelectorAll('.pie-path, .donut-path').forEach(function(el, i) {
                        el.style.cursor = 'pointer';
                        el.addEventListener('click', function() {
                            frappe.set_route('List', 'Sabre Sales Opportunity', {
                                'opportunity_type': labels[i]
                            });
                        });
                    });
                }, 800);

                labels.forEach(function(label, i) {
                    let percent = ((values[i] / total) * 100).toFixed(1);
                    let item = document.createElement('div');
                    item.style.cssText = 'display:flex; align-items:center; gap:6px; cursor:pointer; padding:6px 8px; border-radius:4px; transition: background 0.2s;';
                    item.innerHTML = `
                        <div style="width:10px; height:10px; border-radius:50%; background:${colors[i % colors.length]}; flex-shrink:0;"></div>
                        <div>
                            <div style="font-family:var(--font-stack); font-size:11px; font-weight:600; color:var(--heading-color);">${label}</div>
                            <div style="font-family:var(--font-stack); font-size:11px; color:var(--text-muted);">${values[i]}</div>
                        </div>
                    `;
                    item.addEventListener('mouseenter', function() { item.style.background = 'var(--fg-hover-color)'; });
                    item.addEventListener('mouseleave', function() { item.style.background = 'transparent'; });
                    item.addEventListener('click', function() {
                        frappe.set_route('List', 'Sabre Sales Opportunity', {
                            'opportunity_type': label
                        });
                    });
                    legend_div.appendChild(item);
                });
            }
        }
    });
}, 2500);

